import{_ as p,r as n,o as c,c as r,e as s,a as t,s as e}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Поля формы - October CMS - 3.x","titleTemplate":false,"description":"Узнайте о различных типах полей формы.","frontmatter":{"subtitle":"Узнайте о различных типах полей формы."},"headers":[{"level":2,"title":"Доступные поля","slug":"доступные-поля","link":"#доступные-поля","children":[]},{"level":2,"title":"Свойства полей","slug":"своиства-полеи","link":"#своиства-полеи","children":[{"level":3,"title":"Свойства вкладок","slug":"своиства-вкладок","link":"#своиства-вкладок","children":[]},{"level":3,"title":"Пользовательские типы полей","slug":"пользовательские-типы-полеи","link":"#пользовательские-типы-полеи","children":[]},{"level":3,"title":"Вложенный выбор полей","slug":"вложенныи-выбор-полеи","link":"#вложенныи-выбор-полеи","children":[]},{"level":3,"title":"Фасады полей","slug":"фасады-полеи","link":"#фасады-полеи","children":[]}]},{"level":2,"title":"Условия полей","slug":"условия-полеи","link":"#условия-полеи","children":[{"level":3,"title":"События триггера","slug":"события-триггера","link":"#события-триггера","children":[{"level":4,"title":"Множественные действия","slug":"множественные-деиствия","link":"#множественные-деиствия","children":[]},{"level":4,"title":"Множественные условия значений","slug":"множественные-условия-значении","link":"#множественные-условия-значении","children":[]},{"level":4,"title":"Условия значений с подстановочными символами","slug":"условия-значении-с-подстановочными-символами","link":"#условия-значении-с-подстановочными-символами","children":[]},{"level":4,"title":"Множественные значения полей","slug":"множественные-значения-полеи","link":"#множественные-значения-полеи","children":[]},{"level":4,"title":"Ссылка на родительские поля","slug":"ссылка-на-родительские-поля","link":"#ссылка-на-родительские-поля","children":[]}]},{"level":3,"title":"Конвертер предустановки ввода","slug":"конвертер-предустановки-ввода","link":"#конвертер-предустановки-ввода","children":[]}]}],"relativePath":"3.x/ru/element/form-fields.md","filePath":"3.x/ru/element/form-fields.md"}'),d={name:"3.x/ru/element/form-fields.md"};function i(u,a,k,g,h,m){const o=n("pre-heading"),l=n("post-heading");return c(),r("div",null,[s(o),a[0]||(a[0]=t("h1",null,"Поля формы",-1)),s(l),a[1]||(a[1]=e(`<p>Поля формы, элементы UI формы и виджеты формы — это определения полей, используемые формами, например, текстовое поле ввода. Они обычно применяются в следующих областях:</p><ul><li><a href="./../cms/themes/settings.html">Настройки темы CMS</a></li><li><a href="./../cms/tailor/content-fields.html">Поля контента Tailor</a></li><li><a href="./../extend/forms/form-controller.html">Контроллер форм панели администрирования</a></li><li><a href="./../extend/forms/relation-controller.html">Контроллер связей панели администрирования</a></li></ul><p>Все поля формы идентифицируются по их индивидуальному свойству <strong>type</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token comment"># ...</span>
</code></pre></div><p>Поля формы содержат общие и простые поля. Элементы UI формы — это элементы пользовательского интерфейса, которые можно включить в формы для улучшения дизайна макета. Виджеты формы часто предоставляют более сложную функциональность, плагины обычно предоставляют собственные пользовательские виджеты формы. Поля Tailor — это поля, доступные только внутри чертежей Tailor.</p><h2 id="доступные-поля"><a href="#доступные-поля" class="header-anchor">#</a> Доступные поля</h2><p>Доступны следующие поля формы:</p>`,7)),a[2]||(a[2]=t("div",{class:"content-list-p",markdown:"1"},[t("p",null,[t("a",{href:"./content/field-mixin.html"},"Mixin"),t("a",{href:"./content/field-entries.html"},"Entries"),t("a",{href:"./form/field-text.html"},"Text"),t("a",{href:"./form/field-number.html"},"Number"),t("a",{href:"./form/field-password.html"},"Password"),t("a",{href:"./form/field-email.html"},"Email"),t("a",{href:"./form/field-textarea.html"},"Textarea"),t("a",{href:"./form/field-dropdown.html"},"Dropdown"),t("a",{href:"./form/field-radio.html"},"Radio List"),t("a",{href:"./form/field-balloon.html"},"Balloon Selector"),t("a",{href:"./form/field-checkbox.html"},"Checkbox"),t("a",{href:"./form/field-checkboxlist.html"},"Checkbox List"),t("a",{href:"./form/field-switch.html"},"Switch"),t("a",{href:"./form/widget-codeeditor.html"},"Code Editor"),t("a",{href:"./form/widget-colorpicker.html"},"Color Picker"),t("a",{href:"./form/widget-datatable.html"},"Data Table"),t("a",{href:"./form/widget-datepicker.html"},"Date Picker"),t("a",{href:"./form/widget-fileupload.html"},"File Upload"),t("a",{href:"./form/widget-markdown.html"},"Markdown Editor"),t("a",{href:"./form/widget-mediafinder.html"},"Media Finder"),t("a",{href:"./form/widget-nestedform.html"},"Nested Form"),t("a",{href:"./form/widget-recordfinder.html"},"Record Finder"),t("a",{href:"./form/widget-relation.html"},"Relation"),t("a",{href:"./form/widget-repeater.html"},"Repeater"),t("a",{href:"./form/widget-richeditor.html"},"Rich Editor"),t("a",{href:"./form/widget-pagefinder.html"},"Page Finder"),t("a",{href:"./form/widget-sensitive.html"},"Sensitive"),t("a",{href:"./form/widget-taglist.html"},"Tag List"),t("a",{href:"./form/widget-currency.html"},"Currency"),t("a",{href:"./form/widget-boxes.html"},"Boxes"),t("a",{href:"./form/ui-section.html"},"Section"),t("a",{href:"./form/ui-hint.html"},"Hint"),t("a",{href:"./form/ui-ruler.html"},"Ruler"),t("a",{href:"./form/ui-partial.html"},"Partial")])],-1)),a[3]||(a[3]=e(`<h2 id="своиства-полеи"><a href="#своиства-полеи" class="header-anchor">#</a> Свойства полей</h2><p>Для каждого поля можно указать следующие общие свойства, где применимо.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>имя, отображаемое при показе поля формы пользователю.</td></tr><tr><td><strong>type</strong></td><td>определяет, как это поле должно рендериться. По умолчанию: <code>text</code>.</td></tr><tr><td><strong>span</strong></td><td>выравнивает поле формы по одной стороне. Варианты: <code>auto</code>, <code>left</code>, <code>right</code>, <code>row</code>, <code>full</code>. По умолчанию: <code>full</code>.</td></tr><tr><td><strong>spanClass</strong></td><td>используется вместе со свойством span <code>row</code> для отображения формы в виде сетки Bootstrap, например, <code>spanClass: col-4</code>.</td></tr><tr><td><strong>size</strong></td><td>определяет размер поля для полей, которые его используют, например, textarea. Варианты: <code>tiny</code>, <code>small</code>, <code>large</code>, <code>huge</code>, <code>giant</code>.</td></tr><tr><td><strong>placeholder</strong></td><td>если поле поддерживает значение placeholder.</td></tr><tr><td><strong>comment</strong></td><td>размещает описательный комментарий под полем.</td></tr><tr><td><strong>commentAbove</strong></td><td>размещает комментарий над полем.</td></tr><tr><td><strong>commentHtml</strong></td><td>разрешает HTML-разметку внутри комментария. Варианты: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>default</strong></td><td>определяет значение по умолчанию для поля. Для виджетов <code>dropdown</code>, <code>checkboxlist</code>, <code>radio</code> и <code>balloon-selector</code> можно указать ключ опции для выбора по умолчанию.</td></tr><tr><td><strong>defaultFrom</strong></td><td>берёт значение по умолчанию из значения другого атрибута модели.</td></tr><tr><td><strong>tab</strong></td><td>назначает поле на вкладку.</td></tr><tr><td><strong>cssClass</strong></td><td>назначает CSS-класс контейнеру поля.</td></tr><tr><td><strong>autoFocus</strong></td><td>помечает поле для фокусировки при загрузке формы. По умолчанию: <code>false</code>.</td></tr><tr><td><strong>readOnly</strong></td><td>предотвращает изменение поля. Варианты: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>disabled</strong></td><td>предотвращает изменение поля и исключает его из сохраняемых данных. Варианты: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>hidden</strong></td><td>скрывает поле из представления и исключает его из сохраняемых данных. Варианты: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>stretch</strong></td><td>определяет, растягивается ли это поле по высоте родителя.</td></tr><tr><td><strong>context</strong></td><td>определяет, какой контекст следует использовать при отображении поля. Контекст также можно передать, используя символ <code>@</code> в имени поля, например, <code>name@update</code>.</td></tr><tr><td><strong>dependsOn</strong></td><td>массив имён других полей, от которых <a href="./../extend/forms/field-dependencies.html">зависит</a> это поле. При изменении других полей это поле обновится.</td></tr><tr><td><strong>changeHandler</strong></td><td>имя AJAX-обработчика для вызова при изменении значения поля, необязательно.</td></tr><tr><td><strong>trigger</strong></td><td>определяет условия для этого поля с использованием событий триггера.</td></tr><tr><td><strong>preset</strong></td><td>позволяет начально устанавливать значение поля по значению другого поля, преобразованному с помощью конвертера предустановки ввода.</td></tr><tr><td><strong>required</strong></td><td>размещает красную звёздочку рядом с меткой поля для обозначения обязательности. Убедитесь, что используете <a href="./../extend/database/traits.html">трейт валидации в модели</a>, так как это не обеспечивается контроллером формы.</td></tr><tr><td><strong>attributes</strong></td><td>определяет пользовательские HTML-атрибуты для добавления к элементу поля формы.</td></tr><tr><td><strong>containerAttributes</strong></td><td>определяет пользовательские HTML-атрибуты для добавления к контейнеру поля формы.</td></tr><tr><td><strong>order</strong></td><td>числовой вес при определении порядка отображения, значение по умолчанию увеличивается на 100 для каждого поля.</td></tr><tr><td><strong>permissions</strong></td><td><a href="./../extend/backend/permissions.html">разрешения</a>, которые должен иметь текущий пользователь панели администрирования для использования поля. Поддерживает строку для одного разрешения или массив разрешений, из которых достаточно одного для предоставления доступа.</td></tr></tbody></table></div><h3 id="своиства-вкладок"><a href="#своиства-вкладок" class="header-anchor">#</a> Свойства вкладок</h3><p>Пример определения полей во вкладках.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">username</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> text
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Username
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> User

        <span class="token key atrule">groups</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Groups
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> Groups
</code></pre></div><p>Для каждого определения вкладок, а именно <code>tabs</code> и <code>secondaryTabs</code>, можно указать следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>stretch</strong></td><td>определяет, растягивается ли эта вкладка по высоте родителя.</td></tr><tr><td><strong>defaultTab</strong></td><td>вкладка по умолчанию для назначения полей. По умолчанию: Misc.</td></tr><tr><td><strong>activeTab</strong></td><td>выбранная вкладка при первой загрузке формы, имя или индекс. По умолчанию: <code>1</code></td></tr><tr><td><strong>icons</strong></td><td>назначает иконки вкладкам, используя имена вкладок в качестве ключа.</td></tr><tr><td><strong>lazy</strong></td><td>массив вкладок, загружаемых динамически при клике. Полезно для вкладок с большим количеством контента.</td></tr><tr><td><strong>identifiers</strong></td><td>массив пользовательских HTML-идентификаторов для вкладок. Полезно для показа и скрытия вкладок с помощью JavaScript.</td></tr><tr><td><strong>linkable</strong></td><td>определяет, могут ли вкладки быть связаны с помощью фрагментов URL. По умолчанию: <code>true</code></td></tr><tr><td><strong>cssClass</strong></td><td>назначает CSS-класс контейнеру вкладок.</td></tr><tr><td><strong>paneCssClass</strong></td><td>назначает CSS-класс отдельной панели вкладки. Значение — массив, ключ — индекс или метка вкладки, значение — CSS-класс. Также может быть указано как строка, в этом случае значение будет применено ко всем вкладкам.</td></tr></tbody></table></div><p>Пример применения свойств к вкладкам.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">stretch</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">defaultTab</span><span class="token punctuation">:</span> User
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> text<span class="token punctuation">-</span>blue

    <span class="token key atrule">lazy</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> Groups

    <span class="token key atrule">paneCssClass</span><span class="token punctuation">:</span>
        <span class="token key atrule">1</span><span class="token punctuation">:</span> first<span class="token punctuation">-</span>tab
        <span class="token key atrule">2</span><span class="token punctuation">:</span> second<span class="token punctuation">-</span>tab

    <span class="token key atrule">icons</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>user
        <span class="token key atrule">Groups</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>group

    <span class="token key atrule">identifiers</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> userTab

    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h3 id="пользовательские-типы-полеи"><a href="#пользовательские-типы-полеи" class="header-anchor">#</a> Пользовательские типы полей</h3><p>Существуют различные встроенные типы полей, которые можно использовать для настройки <strong>type</strong>. Также возможно рендерить поле напрямую, указав имя PHP-класса <a href="./../extend/forms/form-widgets.html">виджета поля формы</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> Backend\\FormWidgets\\RichEditor
    <span class="token key atrule">size</span><span class="token punctuation">:</span> huge
</code></pre></div><h3 id="вложенныи-выбор-полеи"><a href="#вложенныи-выбор-полеи" class="header-anchor">#</a> Вложенный выбор полей</h3><div class="language-yaml extra-class"><pre class="language-yaml"><code>avatar<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Avatar
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> will be saved in the Avatar table
</code></pre></div><p>Приведённый выше пример будет получать и сохранять значение в PHP-эквиваленте <code>$record-&gt;avatar-&gt;name</code> или <code>$record-&gt;avatar[&#39;name&#39;]</code> соответственно.</p><h3 id="фасады-полеи"><a href="#фасады-полеи" class="header-anchor">#</a> Фасады полей</h3><p>Иногда вам может потребоваться отобразить поле, предотвратив его отправку. Поле можно определить как фасад, добавив символ подчёркивания (_) перед именем поля. Эти поля очищаются автоматически и больше не сохраняются в модели, как в следующем примере с полем <code>_map</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">address</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">type</span><span class="token punctuation">:</span> text

<span class="token key atrule">_map</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Point your address on the map
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mapviewer
</code></pre></div><h2 id="условия-полеи"><a href="#условия-полеи" class="header-anchor">#</a> Условия полей</h2><p>Иногда вам может потребоваться изменить значение или внешний вид поля формы при определённых условиях, например, скрыть поле ввода при установке флажка или предустановить значение другого поля.</p><h3 id="события-триггера"><a href="#события-триггера" class="header-anchor">#</a> События триггера</h3><p>События триггера определяются с помощью свойства <code>trigger</code> поля формы и представляют собой простое решение на стороне браузера с использованием JavaScript. Они позволяют изменять атрибуты элементов, такие как видимость или значение, на основе состояния другого элемента. Вот пример определения:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">is_delayed</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send later
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> Place a tick in this box if you want to send this message at a later time.
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox

<span class="token key atrule">send_at</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send date
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> field<span class="token punctuation">-</span>indent
    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
        <span class="token key atrule">field</span><span class="token punctuation">:</span> is_delayed
        <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
</code></pre></div><p>В приведённом выше примере поле формы <code>send_at</code> будет отображаться только если поле <code>is_delayed</code> отмечено. Другими словами, поле покажется (action), если другое поле ввода (field) отмечено (condition).</p><p>Определение <code>trigger</code> указывает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>action</strong></td><td>определяет действие, применяемое к этому полю при выполнении условия. Поддерживаемые значения: <code>show</code>, <code>hide</code>, <code>enable</code>, <code>disable</code>, <code>empty</code>, <code>fill[somevalue]</code>.</td></tr><tr><td><strong>field</strong></td><td>ссылка на имя другого поля, которое запускает действие. Пример: <code>color</code> или <code>color[]</code>.</td></tr><tr><td><strong>condition</strong></td><td>определяет условие, которому должно удовлетворять указанное поле для того, чтобы условие считалось <code>true</code>. Поддерживаемые значения: <code>checked</code>, <code>unchecked</code>, <code>value[somevalue]</code>.</td></tr></tbody></table></div><h4 id="множественные-деиствия"><a href="#множественные-деиствия" class="header-anchor">#</a> Множественные действия</h4><p>Вы можете комбинировать несколько действий, разделяя их символом вертикальной черты <code>|</code>. Следующее определение одновременно покажет и очистит поле ввода при выполнении условия триггера.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show<span class="token punctuation">|</span>empty
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
    <span class="token key atrule">field</span><span class="token punctuation">:</span> name
</code></pre></div><h4 id="множественные-условия-значении"><a href="#множественные-условия-значении" class="header-anchor">#</a> Множественные условия значений</h4><p>При использовании условия <code>value[]</code> вы можете проверять несколько значений, передавая дополнительные значения после первого в формате <code>value[][]</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>csv<span class="token punctuation">]</span><span class="token punctuation">[</span>csv_custom<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_format
</code></pre></div><h4 id="условия-значении-с-подстановочными-символами"><a href="#условия-значении-с-подстановочными-символами" class="header-anchor">#</a> Условия значений с подстановочными символами</h4><p>Вы можете проверить, соответствует ли условие <code>value[]</code> нескольким возможным значениям, используя подстановочный символ (<code>*</code>), например, <strong>foo*</strong> соответствует всему, что начинается с &quot;foo&quot;, а <strong>*bar</strong> — всему, что заканчивается на &quot;bar&quot;.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token important">*.mp4</span><span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_name
</code></pre></div><h4 id="множественные-значения-полеи"><a href="#множественные-значения-полеи" class="header-anchor">#</a> Множественные значения полей</h4><p>Некоторые поля, такие как <a href="./form/field-checkboxlist.html">Checkbox List</a> и <a href="./form/widget-taglist.html">Tag List</a>, хранят свои значения как массив. При ссылке на эти поля имя поля должно использовать суффикс массива (<code>[]</code>) для проверки всех возможных значений. Например, если поле <code>colors</code> поддерживает множественные значения, в качестве ссылки следует использовать имя поля <code>colors[]</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>red<span class="token punctuation">]</span><span class="token punctuation">[</span>green<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> colors<span class="token punctuation">[</span><span class="token punctuation">]</span>
</code></pre></div><h4 id="ссылка-на-родительские-поля"><a href="#ссылка-на-родительские-поля" class="header-anchor">#</a> Ссылка на родительские поля</h4><p>Обычно имя поля ссылается на поле того же уровня формы. Например, если это поле находится в <a href="./form/widget-repeater.html">виджете repeater</a>, проверяются только поля того же виджета repeater. Однако если перед именем поля стоит символ каретки <code>^</code>, например: <code>^parent_field</code>, он будет ссылаться на виджет repeater или форму на один уровень выше.</p><p>В приведённом ниже примере поле <code>colors</code> будет показано, когда поле <code>type</code> установлено в <strong>Complex</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Type
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">options</span><span class="token punctuation">:</span>
            <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
            <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex

    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> nestedform
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                <span class="token key atrule">colors</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Colors
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
                    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
                        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
                        <span class="token key atrule">field</span><span class="token punctuation">:</span> ^type
                        <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span>
</code></pre></div><div class="custom-block tip"><p>Кроме того, если используется более одного символа <code>^</code>, он будет ссылаться на соответствующее количество уровней выше: <code>^^grand_parent_field</code>, <code>^^^grand_grand_parent_field</code> и т.д.</p></div><h3 id="конвертер-предустановки-ввода"><a href="#конвертер-предустановки-ввода" class="header-anchor">#</a> Конвертер предустановки ввода</h3><p>Конвертер предустановки ввода определяется с помощью свойства <code>preset</code> поля формы и позволяет конвертировать текст, введённый в элемент, в значение URL, slug или имени файла в другом элементе ввода.</p><p>В этом примере мы автоматически заполним значение поля <code>url</code>, когда пользователь вводит текст в поле <code>title</code>. Если для заголовка набран текст <strong>Hello world</strong>, URL последует с преобразованным значением <strong>/hello-world</strong>. Это поведение будет происходить только когда поле назначения (<code>url</code>) пусто и не тронуто.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">title</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title

<span class="token key atrule">url</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> URL
    <span class="token key atrule">preset</span><span class="token punctuation">:</span>
        <span class="token key atrule">field</span><span class="token punctuation">:</span> title
        <span class="token key atrule">type</span><span class="token punctuation">:</span> url
</code></pre></div><p>В качестве альтернативы значение <code>preset</code> также может быть строкой, ссылающейся только на <strong>field</strong>, опция <code>type</code> тогда по умолчанию будет <strong>slug</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">slug</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Slug
    <span class="token key atrule">preset</span><span class="token punctuation">:</span> title
</code></pre></div><p>Для опции <code>preset</code> доступны следующие параметры:</p><div class="table"><table tabindex="0"><thead><tr><th>Опция</th><th>Описание</th></tr></thead><tbody><tr><td><strong>field</strong></td><td>определяет имя другого поля, из которого берётся значение.</td></tr><tr><td><strong>type</strong></td><td>определяет тип конвертации. Поддерживаемые значения см. ниже.</td></tr><tr><td><strong>prefixInput</strong></td><td>необязательно, добавляет к конвертированному значению префикс значения из указанного элемента ввода, используя CSS-селектор.</td></tr></tbody></table></div><p>Поддерживаются следующие типы:</p><div class="table"><table tabindex="0"><thead><tr><th>Тип</th><th>Описание</th></tr></thead><tbody><tr><td><strong>exact</strong></td><td>копирует точное значение</td></tr><tr><td><strong>slug</strong></td><td>форматирует скопированное значение как slug</td></tr><tr><td><strong>url</strong></td><td>то же, что slug, но с префиксом /</td></tr><tr><td><strong>camel</strong></td><td>форматирует скопированное значение в camelCase</td></tr><tr><td><strong>file</strong></td><td>форматирует скопированное значение как имя файла с заменой пробелов на дефисы</td></tr></tbody></table></div>`,54))])}const b=p(d,[["render",i]]);export{y as __pageData,b as default};
